def count_non_consecutive_subsets(N):
    if N == 0:
        return 1  # Only the empty set
    if N == 1:
        return 2  # {}, {1}

    # a_n = a_{n-1} + a_{n-2}
    # a_1 = 2
    # a_2 = 3

    a_prev2 = 2  # a_1
    a_prev1 = 3  # a_2

    if N == 2:
        return a_prev1

    for n in range(3, N + 1):
        current_a = a_prev1 + a_prev2
        a_prev2 = a_prev1
        a_prev1 = current_a

    return a_prev1

N = 7
result = count_non_consecutive_subsets(N)
print(result)
